aisal-services/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/hail-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/canyon-wind-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load, Ice Dam & Freeze Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/snow-ice-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Leak Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/water-pipe-leak-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Claim Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/wildfire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Earthquake Claim Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/earthquake-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/insurance-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/appraisal-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Snow load","Wildfire claims","Earthquake endorsements"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://utahinsuranceappraiser.com/#website","url":"https://utahinsuranceappraiser.com/","name":"Utah Insurance Appraiser","publisher":{"@id":"https://utahinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://utahinsuranceappraiser.com/claim-terms-glossary/#webpage","url":"https://utahinsuranceappraiser.com/claim-terms-glossary/","name":"Insurance Claim Terms Glossary | ACV, RCV, Umpire & More","description":"Searchable plain-English glossary of property insurance claim terms: ACV, RCV, holdback, appraisal award, umpire, snow load, O&P and more.","inLanguage":"en-US","isPartOf":{"@id":"https://utahinsuranceappraiser.com/#website"},"about":{"@id":"https://utahinsuranceappraiser.com/#business"},"publisher":{"@id":"https://utahinsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://utahinsuranceappraiser.com/claim-terms-glossary/#primaryimage","url":"https://utahinsuranceappraiser.com/assets/img/photos/documents.webp","width":960,"height":601},"breadcrumb":{"@id":"https://utahinsuranceappraiser.com/claim-terms-glossary/#breadcrumb"},"mainEntity":{"@id":"https://utahinsuranceappraiser.com/claim-terms-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://utahinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Glossary","item":"https://utahinsuranceappraiser.com/claim-terms-glossary/"}],"@id":"https://utahinsuranceappraiser.com/claim-terms-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance claim terms glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Often the first payment under a replacement cost policy."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while a damaged home is repaired, sometimes called loss of use."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of covered damage. This is the only question an appraisal panel decides."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition allowing either party to demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by at least two of the three panel members setting the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side selects to value the loss and work with the other appraiser and umpire."},{"@type":"DefinedTerm","name":"Bad faith","description":"A general term for an insurer’s unreasonable handling of a claim. In Utah it is usually analyzed under the implied covenant of good faith in the policy; a legal question for an attorney."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy condition that can reduce a claim payment if the property is insured for less than a required percentage of its value."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage on a homeowners policy, the limit used to calculate percentage deductibles."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, such as detached garages, sheds and fences."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property, or contents, coverage."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing limits, deductibles, endorsements and the policy period."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value due to age, wear and condition, subtracted from replacement cost to find ACV."},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for the cost of removing damaged property and debris after a covered loss, often subject to limits."},{"@type":"DefinedTerm","name":"Earthquake endorsement","description":"An addition to a property policy that covers earthquake damage, typically with a percentage deductible."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage."},{"@type":"DefinedTerm","name":"Estimate review","description":"A line-by-line audit of an insurance estimate to identify missing items and pricing gaps."},{"@type":"DefinedTerm","name":"Extended replacement cost","description":"An endorsement that pays above the dwelling limit, by a set percentage, if rebuilding costs more than expected."},{"@type":"DefinedTerm","name":"Fair rental value","description":"Coverage for lost rent when a rental property can’t be occupied because of a covered loss."},{"@type":"DefinedTerm","name":"First-party claim","description":"A claim you make under your own insurance policy, as opposed to a claim against someone else’s policy."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld until repairs are completed, also called recoverable depreciation."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at a roof’s edge that prevents melting snow from draining and can force water under shingles."},{"@type":"DefinedTerm","name":"Impartial","description":"Without bias toward either side. Many appraisal clauses require appraisers and umpires to be impartial or disinterested."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate describing a task or material, its quantity and its price."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs match in color, texture and appearance."},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage after a loss, such as tarping or water extraction. Policies generally require it."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of meeting current building codes when repairing or rebuilding."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge, often 10% and 10%, for coordinating multiple trades on a repair."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of the dwelling limit rather than a flat dollar amount."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which an insurer may require within a set time after requesting it."},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional who represents a policyholder in presenting and negotiating a claim for a fee."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that can be recovered after repairs are completed under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deduction for depreciation."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full list of damaged items and repairs needed, before pricing."},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of snow and ice on a roof, measured in pounds per square foot."},{"@type":"DefinedTerm","name":"Square (roofing)","description":"100 square feet of roof surface, the standard unit for roofing estimates."},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on roofs above a certain pitch, often 7/12 or 8/12."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add missing items or costs to an insurance estimate after the initial settlement."},{"@type":"DefinedTerm","name":"Surplus lines","description":"Insurance written by carriers not licensed as standard insurers in a state, often for hard-to-place risks."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Wildland-urban interface (WUI)","description":"Areas where homes meet or mix with undeveloped wildland vegetation, raising wildfire risk."}],"@id":"https://utahinsuranceappraiser.com/claim-terms-glossary/#definedtermset"}]}</script>
</head>
